// tests/data/<platform>/ holds fixtures generated by tests/testgen/gen-platforms.sh: the
// "mixed" plan as written by C GDBM built for that platform, plus its C dumps. The C file
// formats differ between platforms in ways the files do not record (struct alignment, char
// signedness, sizeof(long)), so every fixture must be usable without hints.

use gdbm_native::{BinDumpFormat, CharSign, ImportMode, OpenOptions};
use serde::Deserialize;
use std::path::{Path, PathBuf};

#[derive(Deserialize)]
struct Records {
    records: Vec<(String, String)>,
}

#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct Manifest {
    gdbm_version: String,
    char_signed: bool,
    sizeof_long: usize,
    sizeof_off_t: usize,
    alignof_off_t: usize,
    big_endian: bool,
}

struct Platform {
    name: String,
    dir: PathBuf,
    manifest: Manifest,
}

fn data_dir() -> PathBuf {
    [env!("CARGO_MANIFEST_DIR"), "tests", "data"]
        .iter()
        .collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn records() -> Vec<(Vec<u8>, Vec<u8>)> {
    let json = std::fs::read_to_string(data_dir().join("mixed.json")).unwrap();
    serde_json::from_str::<Records>(&json)
        .unwrap()
        .records
        .iter()
        .map(|(k, v)| (unhex(k), unhex(v)))
        .collect()
}

fn platforms() -> Vec<Platform> {
    let mut platforms = std::fs::read_dir(data_dir())
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|dir| dir.join("manifest.json").exists())
        .map(|dir| Platform {
            name: dir.file_name().unwrap().to_string_lossy().into_owned(),
            manifest: serde_json::from_str(
                &std::fs::read_to_string(dir.join("manifest.json")).unwrap(),
            )
            .unwrap(),
            dir,
        })
        .collect::<Vec<_>>();
    platforms.sort_by(|a, b| a.name.cmp(&b.name));
    assert!(platforms.len() >= 5, "missing platform fixtures");
    platforms
}

// Run check on every platform's database(s), collecting failures so one run reports them all.
fn for_each_db(check: impl Fn(&Platform, &Path) -> Result<(), String>) {
    let failures = platforms()
        .iter()
        .flat_map(|p| ["mixed.db", "mixed.db.numsync"].map(|db| (p, p.dir.join(db))))
        .filter_map(|(p, db)| {
            check(p, &db).err().map(|e| {
                format!(
                    "{} {}: {e}",
                    p.name,
                    db.file_name().unwrap().to_string_lossy()
                )
            })
        })
        .collect::<Vec<_>>();
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}

fn verify_contents(
    db: &mut gdbm_native::Gdbm,
    expected: &[(Vec<u8>, Vec<u8>)],
) -> Result<(), String> {
    let len = db.len().map_err(|e| e.to_string())?;
    if len != expected.len() {
        return Err(format!("len {len}, expected {}", expected.len()));
    }
    expected.iter().try_for_each(|(k, v)| {
        match db
            .get::<_, Vec<u8>>(k.as_slice())
            .map_err(|e| e.to_string())?
        {
            Some(got) if got == *v => Ok(()),
            got => Err(format!("key {k:x?}: got {got:x?}")),
        }
    })
}

fn copy_to_temp(db: &Path) -> tempfile::NamedTempFile {
    let tmp = tempfile::NamedTempFile::new().unwrap();
    std::fs::copy(db, tmp.path()).unwrap();
    tmp
}

// Sanity check of the fixtures themselves: the magic number of each database must match the
// byte order and off_t size of the C build that wrote it.
#[test]
fn fixtures_match_manifests() {
    for_each_db(|p, db| {
        let magic = std::fs::read(db).unwrap()[..4].to_vec();
        let value = if p.manifest.big_endian {
            u32::from_be_bytes(magic.try_into().unwrap())
        } else {
            u32::from_le_bytes(magic.try_into().unwrap())
        };
        let numsync = db.extension().is_some_and(|e| e == "numsync");
        let expected = match (p.manifest.sizeof_off_t, numsync) {
            (4, false) => 0x13579acd,
            (8, false) => 0x13579acf,
            (4, true) => 0x13579ad0,
            (_, true) => 0x13579ad1,
            _ => 0,
        };
        (value == expected)
            .then_some(())
            .ok_or(format!("magic {value:#x}, expected {expected:#x}"))
    });
}

#[test]
fn open_without_hints() {
    let n = records().len();
    for_each_db(|_, db| {
        let mut db = OpenOptions::new().open(db).map_err(|e| e.to_string())?;
        match db.len().map_err(|e| e.to_string())? {
            len if len == n => Ok(()),
            len => Err(format!("len {len}, expected {n}")),
        }
    });
}

#[test]
fn read_all_records() {
    let expected = records();
    for_each_db(|_, db| {
        let tmp = copy_to_temp(db);
        let mut db = OpenOptions::new()
            .write(true)
            .open(tmp.path())
            .map_err(|e| e.to_string())?;
        verify_contents(&mut db, &expected)
    });
}

// Replace, remove and add records (including non-ASCII keys) in each C database, then
// reopen and check everything, so writes use the platform's layout and hashing.
#[test]
fn modify_and_reopen() {
    for_each_db(|_, db| {
        let mut expected = records();
        let tmp = copy_to_temp(db);
        {
            let mut db = OpenOptions::new()
                .write(true)
                .open(tmp.path())
                .map_err(|e| e.to_string())?;
            for (i, (k, v)) in expected.iter_mut().enumerate() {
                if i % 3 == 0 {
                    *v = format!("new value {i}").into_bytes();
                    db.insert(k.as_slice(), v.as_slice())
                        .map_err(|e| e.to_string())?;
                }
            }
            let removed = expected.split_off(expected.len() - 50);
            for (k, _) in &removed {
                db.remove(k.as_slice()).map_err(|e| e.to_string())?;
            }
            for i in 0..100 {
                let (k, v) = (
                    format!("nouveau clé {i} ✓").into_bytes(),
                    vec![b'n'; i * 13],
                );
                db.insert(k.as_slice(), v.as_slice())
                    .map_err(|e| e.to_string())?;
                expected.push((k, v));
            }
            db.sync().map_err(|e| e.to_string())?;
        }

        let mut db = OpenOptions::new()
            .write(true)
            .open(tmp.path())
            .map_err(|e| e.to_string())?;
        verify_contents(&mut db, &expected)
    });
}

fn for_each_platform(check: impl Fn(&Platform) -> Result<(), String>) {
    let failures = platforms()
        .iter()
        .filter_map(|p| check(p).err().map(|e| format!("{}: {e}", p.name)))
        .collect::<Vec<_>>();
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}

fn new_db(dir: &tempfile::TempDir) -> gdbm_native::Gdbm {
    OpenOptions::new()
        .write(true)
        .create(true)
        .open(dir.path().join("db"))
        .unwrap()
}

// the C binary dump length field is a C long, in the platform's byte order
fn bin_format(p: &Platform) -> BinDumpFormat {
    match (p.manifest.sizeof_long, p.manifest.big_endian) {
        (4, _) => BinDumpFormat::Long32,
        (_, false) => BinDumpFormat::Long64Le,
        (_, true) => BinDumpFormat::Long64Be,
    }
}

#[test]
fn import_c_ascii_dumps() {
    let expected = records();
    for_each_platform(|p| {
        let dir = tempfile::tempdir().unwrap();
        let mut db = new_db(&dir);
        let mut f = std::fs::File::open(p.dir.join("mixed.txt")).unwrap();
        let info = db
            .import_ascii(&mut f, ImportMode::Replace)
            .map_err(|e| e.to_string())?;
        if info.count != expected.len() || info.numsync != Some(false) || info.mode.is_none() {
            return Err(format!("dump info {info:?}"));
        }
        verify_contents(&mut db, &expected)
    });
}

#[test]
fn import_c_binary_dumps() {
    let expected = records();
    for_each_platform(|p| {
        // detected, then explicit
        for format in [None, Some(bin_format(p))] {
            let dir = tempfile::tempdir().unwrap();
            let mut db = new_db(&dir);
            let mut f = std::fs::File::open(p.dir.join("mixed.bin")).unwrap();
            let count = db
                .import_bin(&mut f, format, ImportMode::Replace)
                .map_err(|e| format!("{format:?}: {e}"))?;
            if count != expected.len() {
                return Err(format!("{format:?}: imported {count}"));
            }
            verify_contents(&mut db, &expected).map_err(|e| format!("{format:?}: {e}"))?;
        }
        Ok(())
    });
}

// Dumps of a C database are identical to C GDBM's own, after the header (which names the
// software version and date) -- except that gdbm-native writes an empty line for empty values,
// since C GDBM's gdbm_load cannot load C GDBM's own encoding of them.
#[test]
fn export_matches_c_binary_dumps() {
    fn records_part(dump: &[u8]) -> &[u8] {
        let mut newlines = dump.iter().enumerate().filter(|&(_, &b)| b == b'\n');
        &dump[newlines.nth(3).unwrap().0 + 1..]
    }

    for_each_platform(|p| {
        let mut db = OpenOptions::new()
            .open(p.dir.join("mixed.db"))
            .map_err(|e| e.to_string())?;
        let mut ours = Vec::new();
        db.export_bin(&mut ours, bin_format(p))
            .map_err(|e| e.to_string())?;
        let theirs = std::fs::read(p.dir.join("mixed.bin")).unwrap();
        (records_part(&ours) == records_part(&theirs))
            .then_some(())
            .ok_or("binary dump differs from C".to_string())
    });
}

#[test]
fn export_matches_c_ascii_dumps() {
    fn records_part(dump: &str) -> &str {
        &dump[dump.find("# End of header\n").unwrap()..]
    }

    for_each_platform(|p| {
        let mut db = OpenOptions::new()
            .open(p.dir.join("mixed.db"))
            .map_err(|e| e.to_string())?;
        let mut ours = Vec::new();
        db.export_ascii(&mut ours, None::<&str>)
            .map_err(|e| e.to_string())?;
        let ours = String::from_utf8(ours).unwrap().replace("\n\n", "\n");
        let theirs = std::fs::read_to_string(p.dir.join("mixed.txt")).unwrap();
        if !ours.contains("\n#:format=standard\n") {
            return Err("missing #:format".to_string());
        }
        (records_part(&ours) == records_part(&theirs))
            .then_some(())
            .ok_or("ASCII dump differs from C".to_string())
    });
}

// CharSign is detected from the database on first use of a key with a byte >= 0x80, and matches
// the char signedness of the C build that wrote it. ASCII-only use leaves it undetermined.
#[test]
fn char_sign_detected() {
    let records = records();
    let ascii = records.iter().find(|(k, _)| k.is_ascii()).unwrap();
    let non_ascii = records.iter().find(|(k, _)| !k.is_ascii()).unwrap();
    for_each_db(|p, db| {
        let mut db = OpenOptions::new().open(db).map_err(|e| e.to_string())?;
        db.get::<_, Vec<u8>>(ascii.0.as_slice())
            .map_err(|e| e.to_string())?;
        if let Some(sign) = db.char_sign() {
            return Err(format!("decided {sign:?} from an ASCII key"));
        }
        db.get::<_, Vec<u8>>(non_ascii.0.as_slice())
            .map_err(|e| e.to_string())?;
        let expected = if p.manifest.char_signed {
            CharSign::Signed
        } else {
            CharSign::Unsigned
        };
        (db.char_sign() == Some(expected))
            .then_some(())
            .ok_or(format!(
                "detected {:?}, expected {expected:?}",
                db.char_sign()
            ))
    });
}

// An explicit CharSign is used as given, so the wrong one finds no non-ASCII keys.
#[test]
fn char_sign_override() {
    let records = records();
    for_each_db(|p, db| {
        let wrong = if p.manifest.char_signed {
            CharSign::Unsigned
        } else {
            CharSign::Signed
        };
        let mut db = OpenOptions::new()
            .char_sign(wrong)
            .open(db)
            .map_err(|e| e.to_string())?;
        let found = records
            .iter()
            .filter(|(k, _)| !k.is_ascii())
            .filter(|(k, _)| db.contains_key(k.as_slice()).unwrap())
            .count();
        (db.char_sign() == Some(wrong) && found == 0)
            .then_some(())
            .ok_or(format!(
                "{found} non-ASCII keys found with the wrong CharSign"
            ))
    });
}
